WITH enriched AS (SELECT id, session_id, event_type, duration_sec, SUM(duration_sec) OVER (PARTITION BY page) AS page_sum_duration_sec, NTILE(4) OVER (PARTITION BY event_type ORDER BY duration_sec, id) AS duration_sec_bucket, COUNT(duration_sec) OVER (PARTITION BY session_id ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_count_7d, ROW_NUMBER() OVER (PARTITION BY TO_DATE(event_time), page ORDER BY event_time, id) AS event_seq, SUM(duration_sec) OVER (PARTITION BY page, event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec FROM web_events) SELECT s.id, s.session_id, s.event_type, s.page_sum_duration_sec, s.duration_sec_bucket, s.duration_sec_count_7d, s.event_seq, (SELECT MIN(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS min_web_event_duration_sec FROM enriched s;
